import os
import tempfile
import pytest
from envcfg import ConfigError, load_config


def test_defaults_only():
    cfg = load_config({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"a = 10\nb = 20")
        toml_path = f.name
    try:
        cfg = load_config({"a": 1, "b": 2}, toml_path)
        assert cfg == {"a": 10, "b": 20}
    finally:
        os.unlink(toml_path)


def test_nested_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"server = { port = 8080, host = \"0.0.0.0\" }")
        toml_path = f.name
    try:
        cfg = load_config({"server": {"port": 80}}, toml_path)
        assert cfg == {"server": {"port": 8080, "host": "0.0.0.0"}}
    finally:
        os.unlink(toml_path)


def test_env_overrides_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"port = 9000")
        toml_path = f.name
    try:
        os.environ["APP__PORT"] = "1234"
        cfg = load_config({"port": 1}, toml_path)
        assert cfg == {"port": 1234}
    finally:
        os.unlink(toml_path)
        del os.environ["APP__PORT"]


def test_precedence_defaults_toml_env():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"port = 9000")
        toml_path = f.name
    try:
        os.environ["APP__PORT"] = "1234"
        cfg = load_config({"port": 1}, toml_path)
        assert cfg == {"port": 1234}
    finally:
        os.unlink(toml_path)
        del os.environ["APP__PORT"]


def test_int_coerce():
    cfg = load_config({"port": 80}, env={"APP__PORT": "8080"})
